#include <bits/stdc++.h>
using namespace std;
int findMaxConsecutiveOnes(vector<int> &nums)
{
    int count = 0, temp = -1;
    for (int i = 0; i < nums.size(); i++)
    {
        if (nums[i] == 1)
        {
            count++;
        }
        else
        {
            if (count > temp)
                temp = count;
            count = 0;
        }
    }
    return count > temp ? count : temp;
}
